21→/**
22→ * Represents a config URL that may point to a USPS endpoint
23→ *
24→ * @SuppressWarnings(PHPMD.Superglobals)
25→ */
26→class UspsUrl extends Value
27→{
28→    /**
29→     * @var Url
30→     */
31→    private Url $url;
32→
33→    /**
34→     * @param Context $context
35→     * @param Registry $registry
36→     * @param ScopeConfigInterface $config
37→     * @param TypeListInterface $cacheTypeList
38→     * @param Url $url
39→     * @param AbstractResource|null $resource
40→     * @param AbstractDb|null $resourceCollection
41→     * @param array $data
42→     */
43→    public function __construct(
44→        Context $context,
45→        Registry $registry,
46→        ScopeConfigInterface $config,
47→        TypeListInterface $cacheTypeList,
48→        Url $url,
49→        ?AbstractResource $resource = null,
50→        ?AbstractDb $resourceCollection = null,
51→        array $data = []
52→    ) {
53→        $this->url = $url;
54→        parent::__construct($context, $registry, $config, $cacheTypeList, $resource, $resourceCollection, $data);
55→    }
56→
57→    /**
58→     * @inheritdoc
59→     *
60→     * @throws ValidatorException
61→     */
62→    public function beforeSave()
63→    {
64→        $isValid = $this->url->isValid($this->getValue());
65→        if ($isValid) {
66→            // phpcs:ignore Magento2.Functions.DiscouragedFunction
67→            $host = parse_url((string)$this->getValue(), \PHP_URL_HOST);
68→        }
69→        if (!$isValid || (!empty($host) && !preg_match("/(?:.+\.|^)(usps|shippingapis)\.com$/i", $host))) {
70→            throw new ValidatorException(__('USPS API endpoint URL\'s must use usps.com or shippingapis.com'));
71→        }
72→        
73→        return parent::beforeSave();
74→    }
75→}
