21→
22→/**
23→ * Represents a config URL that may point to a Fedex endpoint
24→ */
25→class FedexUrl extends Value
26→{
27→    /**
28→     * @var Url
29→     */
30→    private Url $url;
31→    /**
32→     * @param Context $context
33→     * @param Registry $registry
34→     * @param ScopeConfigInterface $config
35→     * @param TypeListInterface $cacheTypeList
36→     * @param AbstractResource|null $resource
37→     * @param AbstractDb|null $resourceCollection
38→     * @param Url $url
39→     * @param array $data
40→     */
41→    public function __construct(
42→        Context $context,
43→        Registry $registry,
44→        ScopeConfigInterface $config,
45→        TypeListInterface $cacheTypeList,
46→        ?AbstractResource $resource,
47→        ?AbstractDb $resourceCollection,
48→        Url $url,
49→        array $data = []
50→    ) {
51→        parent::__construct($context, $registry, $config, $cacheTypeList, $resource, $resourceCollection, $data);
52→        $this->url = $url;
53→    }
54→
55→    /**
56→     * @inheritDoc
57→     *
58→     * @return AbstractModel
59→     * @throws ValidatorException
60→     */
61→    public function beforeSave(): AbstractModel
62→    {
63→        $isValid = $this->url->isValid($this->getValue(), ['http', 'https']);
64→        if ($isValid) {
65→            // phpcs:ignore Magento2.Functions.DiscouragedFunction
66→            $host = parse_url((string)$this->getValue(), \PHP_URL_HOST);
67→        }
68→        if (!$isValid || (!empty($host) && !preg_match('/(?:.+\.|^)fedex\.com$/i', $host))) {
69→            throw new ValidatorException(__('Fedex API endpoint URL\'s must use fedex.com'));
70→        }
71→
72→        return parent::beforeSave();
73→    }
74→}
